export type TopicChip = {
  label: string;
  /** Query string fed into caption search — chips only filter the index. */
  query: string;
};

/** Per-meeting caption file shape (vimeoId omitted to save bytes). */
export type LcpsCaptionSlice = {
  start: number;
  end: number;
  text: string;
};

export type LcpsCaptionWindow = LcpsCaptionSlice & {
  vimeoId: string;
};

export type LcpsMeetingKind =
  | "full_board"
  | "committee"
  | "closed"
  | "appeals"
  | "other";

export type LcpsMeeting = {
  id: string;
  vimeoId: string;
  title: string;
  dateLabel: string;
  duration: string;
  playerUrl: string;
  boardDocsUrl: string;
  lcpsTvUrl: string;
  /** Static JSON under /files/find-the-moment/loudoun-lcps/{vimeoId}.json */
  windowsUrl: string;
  windowCount: number;
  /** Meeting class for Find the Moment filters. Default UI shows All. */
  kind: LcpsMeetingKind;
  /** Optional display name for committee / closed / appeals rows. */
  committeeName?: string;
};

export type LcpsBoardMember = {
  name: string;
  district: string;
  role: string;
};

/** Thin public School Board roster — name, district, role. No bios, finance, or findings. */
